#!/usr/bin/env python3
"""Verifier for the SQLite WAL recovery task. Exits 0 iff /data/recovered.json is correct."""
import json, os, sys

PATH = "/data/recovered.json"
# Expected content: all rows of table `records` in /data/database.db read together with its
# WAL (/data/database.db-wal). Recomputed with sqlite3 on the task's own files:
# 15 rows, id 1..15, name 'record<id>', value id*10.
EXPECTED = [{"id": i, "name": f"record{i}", "value": i * 10} for i in range(1, 16)]

fails = []
def fail(msg):
    fails.append(msg)

def main():
    if not os.path.isfile(PATH):
        fail("missing /data/recovered.json"); return
    try:
        with open(PATH, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception as e:
        fail(f"invalid JSON: {e}"); return
    if not isinstance(data, list):
        fail(f"top level must be a list, got {type(data).__name__}"); return
    if len(data) != 15:
        fail(f"expected 15 records, got {len(data)}")
    for i, r in enumerate(data):
        if not isinstance(r, dict):
            fail(f"record {i} is not an object"); continue
        if set(r.keys()) != {"id", "name", "value"}:
            fail(f"record {i} keys {sorted(r.keys())} != ['id','name','value']")
        for k, t in (("id", int), ("value", int)):
            v = r.get(k)
            if not isinstance(v, t) or isinstance(v, bool):
                fail(f"record {i} field {k}={v!r} is not an integer")
        if not isinstance(r.get("name"), str):
            fail(f"record {i} name {r.get('name')!r} is not a string")
    if fails:
        return
    ids = [r["id"] for r in data]
    if ids != sorted(ids):
        fail(f"not sorted by id: {ids}")
    if data != EXPECTED:
        exp = {e["id"]: e for e in EXPECTED}
        got = {r["id"]: r for r in data}
        for i in sorted(set(exp) | set(got)):
            if exp.get(i) != got.get(i):
                fail(f"id {i}: expected {exp.get(i)}, got {got.get(i)}")
        if len(ids) != len(set(ids)):
            fail("duplicate ids")

main()
if fails:
    for m in fails:
        print("FAIL:", m)
    sys.exit(1)
print("PASS: recovered.json has all 15 records, correct values, sorted by id")
sys.exit(0)
E
